#!/usr/bin/env node
interface Config {
    obfuscate?: boolean;
    minify?: boolean;
    entry?: {
        server?: string;
        client?: string;
    };
    watch?: {
        server?: string[];
        client?: string[];
        all?: string[];
    };
    resource?: {
        directory?: string;
    };
    copy?: {
        from: string;
        to: string;
    }[];
    skipCopyDuringWatch?: boolean;
}

/**
 * @interface Config
 * Configuration options for setting up the project's build and development behavior.
 *
 * @var obfuscate  Optional boolean. If true, the code will be obfuscated to increase security by making it harder to read.
 * @var minify     Optional boolean. If true, the code will be minified, reducing its size and improving load performance.
 * @var watch      Optional array of strings. Specifies a list of paths to monitor for changes during development.
 * @var resource   Optional object. Contains resource-specific settings for configuring the working directory.
 * @var resource.directory  Optional string. The directory path to store resources for the project.
 * @var copy       Optional array of objects. Defines paths for files to be copied from one location to another.
 * @var copy.from  String. Source path from which files should be copied.
 * @var copy.to    String. Destination path where files should be copied.
 * @var skipCopyDuringWatch  Optional boolean. If true, the copy process will be skipped during watch mode.
 */
/**
 * @function defineConfig
 * Sets up the project configuration using the provided options.
 *
 * @param config  An object containing configuration options as defined in the `Config` interface.
 * @return The finalized configuration object.
 *
 * This function allows setting up the project's configuration by providing options such as obfuscation,
 * minification, directory paths, and file copying paths, which tailor the build and development environment.
 */
declare function defineConfig(config: Config): Config;

declare const args: string[];
declare const cwd: string;
declare const isDev: boolean;

export { type Config as CompilerConfig, args, cwd, defineConfig, isDev };
